parameters.jsCode:
// Checks the AI answer against the allowed lists in 'Alert Settings'.
// If the AI answer is missing or invalid, the report is routed for human triage (fail-safe).
const S = $('Alert Settings').first().json;
const first = $input.first().json;
const ai = first && first.output && typeof first.output === 'object' ? first.output : null;

const SEVERITIES = ['Critical', 'High', 'Medium', 'Low', 'Not an Emergency'];
const categoryNames = S.categories.map(c => c.name);
const teamNames = Object.keys(S.teams);
const pick = (value, list) => list.find(x => x.toLowerCase() === String(value ?? '').trim().toLowerCase());

const warnings = [];
let severity = ai ? pick(ai.severity, SEVERITIES) : undefined;
let category, team, reason;
let aiOk = true;

if (!severity) {
  aiOk = false;
  severity = pick(S.fallback_severity, SEVERITIES) || 'High';
  category = S.fallback_category;
  team = S.default_team;
  reason = 'AI classification was unavailable or invalid. Routed for manual triage.';
  warnings.push('ai_unavailable_or_invalid');
} else {
  category = pick(ai.category, categoryNames);
  if (!category) { category = S.fallback_category; warnings.push('category_not_in_allowed_list'); }
  reason = String(ai.severity_reason ?? '').trim();
  if (!reason) { reason = 'No reason given by AI.'; warnings.push('missing_reason'); }
  team = pick(ai.required_team, teamNames);
  if (severity === 'Not an Emergency') {
    team = 'N/A';
  } else if (!team) {
    team = S.default_team;
    warnings.push('team_not_in_allowed_list');
  }
}

return [{
  json: {
    citizen_name: S.citizen_name,
    phone: S.phone,
    description: S.description,
    location: S.location,
    received_at: S.received_at,
    category,
    severity,
    severity_reason: reason,
    required_team: team,
    is_emergency: severity !== 'Not an Emergency',
    ai_ok: aiOk,
    warnings,
  },
}];

// Looks for an open incident with the same category and a matching location inside the merge window.
// If found, the existing incident ID is reused. Otherwise a new ID is created.
const C = $('Validate AI Classification').first().json;
const S = $('Alert Settings').first().json;
const rows = [];

const now = $now;
const nowIso = now.toISO();
const nowMs = now.toMillis();

const RANK = { 'Not an Emergency': 0, Low: 1, Medium: 2, High: 3, Critical: 4 };
const SLA_MIN = {
  Critical: Number(S.sla_critical_minutes),
  High: Number(S.sla_high_minutes),
  Medium: Number(S.sla_medium_minutes),
  Low: 0,
  'Not an Emergency': 0,
};
const windowMs = Number(S.merge_window_minutes) * 60000;

const norm = s => String(s ?? '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
const sameLocation = (a, b) => {
  a = norm(a); b = norm(b);
  if (!a || !b) return false;
  return a === b || (Math.min(a.length, b.length) >= 4 && (a.includes(b) || b.includes(a)));
};
const withinWindow = r => {
  const t = new Date(r.created_at).getTime();
  return !isNaN(t) && nowMs - t >= 0 && nowMs - t <= windowMs;
};

const match = rows
  .filter(r =>
    String(r.category ?? '').toLowerCase() === String(C.category).toLowerCase() &&
    String(r.status ?? '').toUpperCase() !== 'RESOLVED' &&
    sameLocation(r.location, C.location) &&
    withinWindow(r))
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0];

const deadlineFor = sev => (SLA_MIN[sev] > 0 ? now.plus({ minutes: SLA_MIN[sev] }).toISO() : '');
let out;

if (match) {
  // ---- Duplicate: merge into the existing incident
  const oldRank = RANK[match.severity] ?? 0;
  const newRank = RANK[C.severity] ?? 0;
  const escalated = newRank > oldRank;

  const severity = escalated ? C.severity : match.severity;
  const reason = escalated ? C.severity_reason : match.severity_reason;
  const team = escalated ? C.required_team : match.required_team;

  let status = String(match.status || 'NEW').toUpperCase();
  if (status === 'NOT_EMERGENCY' && severity !== 'Not an Emergency') status = 'NEW';

  let ackDeadline = match.ack_deadline ?? '';
  let escalationStatus = match.escalation_status ?? '';
  if (escalated && status === 'NEW') {
    ackDeadline = deadlineFor(severity);
    if (SLA_MIN[severity] > 0 && ['', 'NOT_REQUIRED'].includes(String(escalationStatus).toUpperCase())) {
      escalationStatus = 'NONE';
    }
  }

  out = {
    incident_id: match.incident_id,
    duplicate: true,
    severity_escalated: escalated,
    report_count: (Number(match.report_count) || 1) + 1,
    category: match.category,
    severity, reason, team, status,
    row: {
      incident_id: match.incident_id,
      citizen_name: match.citizen_name ?? '',
      phone: match.phone ?? '',
      description: match.description ?? '',
      location: match.location ?? '',
      category: match.category,
      severity,
      severity_reason: reason,
      required_team: team,
      status,
      report_count: (Number(match.report_count) || 1) + 1,
      duplicate: 'YES',
      created_at: match.created_at,
      last_updated: nowIso,
      ack_deadline: ackDeadline,
      acknowledged_at: match.acknowledged_at ?? '',
      escalation_status: escalationStatus,
      escalated_at: match.escalated_at ?? '',
    },
  };
} else {
  // ---- New incident: build a unique ID (no spreadsheet row counting)
  const codeByName = {};
  for (const c of S.categories) codeByName[String(c.name).toLowerCase()] = c.code;
  const catCode = String(codeByName[String(C.category).toLowerCase()]
    || String(C.category).replace(/[^A-Za-z]/g, '').slice(0, 3) || 'GEN').toUpperCase();
  const datePart = now.toFormat('ddLL');
  const used = new Set(rows.map(r => String(r.incident_id)));
  const ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const randomPart = () => Array.from({ length: 4 }, () => ALPHABET[Math.floor(Math.random() * 36)]).join('');
  let id;
  let tries = 0;
  do { id = `${S.city_code}-${catCode}-${datePart}-${randomPart()}`; tries++; } while (used.has(id) && tries < 100);

  const status = C.is_emergency ? 'NEW' : 'NOT_EMERGENCY';
  out = {
    incident_id: id,
    duplicate: false,
    severity_escalated: false,
    report_count: 1,
    category: C.category,
    severity: C.severity, reason: C.severity_reason, team: C.required_team, status,
    row: {
      incident_id: id,
      citizen_name: C.citizen_name,
      phone: C.phone,
      description: C.description,
      location: C.location,
      category: C.category,
      severity: C.severity,
      severity_reason: C.severity_reason,
      required_team: C.required_team,
      status,
      report_count: 1,
      duplicate: 'NO',
      created_at: nowIso,
      last_updated: nowIso,
      ack_deadline: deadlineFor(C.severity),
      acknowledged_at: '',
      escalation_status: SLA_MIN[C.severity] > 0 ? 'NONE' : 'NOT_REQUIRED',
      escalated_at: '',
    },
  };
}

return [{
  json: {
    incident_id: out.incident_id,
    duplicate: out.duplicate,
    severity_escalated: out.severity_escalated,
    report_count: out.report_count,
    category: out.category,
    severity: out.severity,
    severity_reason: out.reason,
    required_team: out.team,
    status: out.status,
    is_emergency: C.is_emergency,
    ai_ok: C.ai_ok,
    // Latest report details, used for alerts
    description: C.description,
    location: C.location,
    reported_at_display: now.toFormat('dd LLL yyyy, hh:mm a'),
    alert_route: (out.duplicate && !out.severity_escalated) ? 'Duplicate - No Alert' : out.severity,
    row: out.row,
  },
}];

// Builds one item per person to alert. Low / Not an Emergency / quiet duplicates get one empty item
// so the workflow can continue and save the incident.
const I = $input.first().json;
const S = $('Alert Settings').first().json;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const team = S.teams[I.required_team] || S.teams[S.default_team] || {};

let recipients = [];
if (['Critical', 'High', 'Medium'].includes(I.alert_route)) {
  recipients.push({ role: 'Response Team (' + I.required_team + ')', telegram_chat_id: team.telegram_chat_id, email: team.email });
  if (['Critical', 'High'].includes(I.alert_route)) {
    recipients.push({ role: 'Supervisor', telegram_chat_id: S.supervisor_telegram_chat_id, email: S.supervisor_email });
  }
  if (I.alert_route === 'Critical') {
    recipients.push({ role: 'Department Head', telegram_chat_id: S.dept_head_telegram_chat_id, email: S.dept_head_email });
  }
}

if (recipients.length === 0) {
  return [{ json: { alert_route: I.alert_route, role: 'none' } }];
}

const updateNote = I.duplicate ? `UPDATE: severity raised (now ${I.report_count} reports)\n` : '';
const telegramText =
`[DEMO / SIMULATION] 🚨 EMERGENCY ALERT - ${I.severity.toUpperCase()}
${updateNote}Incident ID: ${I.incident_id}
Category: ${I.category}
Severity: ${I.severity}
Location: ${I.location}
Description: ${I.description}
Required team: ${I.required_team}
Reported at: ${I.reported_at_display}`;

const subject = `[DEMO] [${I.severity.toUpperCase()}] ${I.category} - ${I.location} (${I.incident_id})`;
const html = `<div style="font-family:Arial,sans-serif;max-width:600px;">
<h2 style="color:#b91c1c;margin-bottom:4px;">Emergency Alert - ${esc(I.severity)}</h2>
${I.duplicate ? '<p style="color:#b45309;"><b>Update:</b> severity raised. Total reports: ' + I.report_count + '</p>' : ''}
<table style="border-collapse:collapse;width:100%;">
<tr><td style="padding:6px;"><b>Incident ID</b></td><td style="padding:6px;">${esc(I.incident_id)}</td></tr>
<tr><td style="padding:6px;"><b>Category</b></td><td style="padding:6px;">${esc(I.category)}</td></tr>
<tr><td style="padding:6px;"><b>Severity</b></td><td style="padding:6px;">${esc(I.severity)}</td></tr>
<tr><td style="padding:6px;"><b>Location</b></td><td style="padding:6px;">${esc(I.location)}</td></tr>
<tr><td style="padding:6px;"><b>Description</b></td><td style="padding:6px;">${esc(I.description)}</td></tr>
<tr><td style="padding:6px;"><b>Required team</b></td><td style="padding:6px;">${esc(I.required_team)}</td></tr>
<tr><td style="padding:6px;"><b>Reported at</b></td><td style="padding:6px;">${esc(I.reported_at_display)}</td></tr>
</table></div>`;

return recipients.map(r => ({
  json: {
    alert_route: I.alert_route,
    role: r.role,
    telegram_chat_id: String(r.telegram_chat_id ?? ''),
    email: String(r.email ?? ''),
    telegram_text: telegramText + '\nYou are alerted as: ' + r.role,
    email_subject: subject,
    email_html: html,
  },
}));

// Builds the JSON answer for the citizen. No phone number or name is returned.
const I = $('Check Duplicates and Build Incident').first().json;
const END = ' In life-threatening danger, also call 112.';

let message;
if (I.duplicate) {
  message = `This incident was already reported. Your report was added to incident ${I.incident_id} (${I.report_count} reports so far).`;
  if (I.severity_escalated) message += ` The severity was raised to ${I.severity} and the team has been alerted again.`;
} else if (!I.is_emergency) {
  message = `Your report was recorded as ${I.incident_id}, but it does not look like an emergency. It has been logged for follow-up.`;
} else if (['Critical', 'High', 'Medium'].includes(I.severity)) {
  message = `Your report is registered as incident ${I.incident_id}. Notifications to configured demo recipients were attempted; verify delivery in Telegram/Gmail.`;
} else {
  message = `Your report is registered as incident ${I.incident_id}. It has been recorded for follow-up.`;
}

return [{
  json: {
    response: {
      incident_id: I.incident_id,
      category: I.category,
      severity: I.severity,
      severity_reason: I.severity_reason,
      required_team: I.required_team,
      status: I.status,
      duplicate: I.duplicate,
      report_count: I.report_count,
      message: message + END,
    },
  },
}];

// Checks that the requested status change is allowed.
const row = $input.first().json;
const req = $('Normalize Status Request').first().json;

const TRANSITIONS = {
  NEW: ['ACKNOWLEDGED', 'RESOLVED'],
  ACKNOWLEDGED: ['IN_PROGRESS', 'RESOLVED'],
  IN_PROGRESS: ['RESOLVED'],
  RESOLVED: [],
  NOT_EMERGENCY: [],
};

const current = String(row.status ?? '').toUpperCase();
const next = (TRANSITIONS[current] || []);
const allowed = next.includes(req.new_status);
const nowIso = $now.toISO();

return [{
  json: {
    allowed,
    incident_id: row.incident_id,
    current_status: current,
    requested_status: req.new_status,
    reason: allowed ? '' : `Cannot change status from ${current} to ${req.new_status}. Allowed next status: ${next.length ? next.join(', ') : 'none (final status)'}.`,
    last_updated: nowIso,
    acknowledged_at: row.acknowledged_at || nowIso,
    row,
  },
}];

const c = $('Check Status Transition').first().json;
const r = c.row;
return [{
  json: {
    response: {
      incident_id: c.incident_id,
      category: r.category,
      severity: r.severity,
      location: r.location,
      required_team: r.required_team,
      previous_status: c.current_status,
      status: c.requested_status,
      report_count: Number(r.report_count) || 1,
      acknowledged_at: c.acknowledged_at,
      escalation_status: r.escalation_status,
      last_updated: c.last_updated,
      message: 'Incident status updated.',
    },
  },
}];

// Finds NEW (unacknowledged) incidents whose deadline has passed and that were not escalated yet.
const rows = $input.all().map(i => i.json).filter(r => r.incident_id);
const now = $now;
const nowMs = now.toMillis();
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const pending = rows.filter(r => String(r.status ?? '').toUpperCase() === 'NEW');

const overdue = pending
  .filter(r => {
    const t = new Date(r.ack_deadline).getTime();
    return String(r.escalation_status ?? '').toUpperCase() === 'NONE' && r.ack_deadline && !isNaN(t) && t <= nowMs;
  })
  .map(r => {
    const mins = Math.max(0, Math.round((nowMs - new Date(r.ack_deadline).getTime()) / 60000));
    const text =
`[DEMO / SIMULATION] ⚠️ ESCALATION: NO ACKNOWLEDGMENT
Incident ID: ${r.incident_id}
Category: ${r.category}
Severity: ${r.severity}
Location: ${r.location}
Description: ${r.description}
Required team: ${r.required_team}
Reported at: ${r.created_at}
Acknowledgment deadline: ${r.ack_deadline}
Overdue by: ${mins} minute(s)`;
    const html = `<div style="font-family:Arial,sans-serif;max-width:600px;">
<h2 style="color:#b91c1c;">Escalation: incident not acknowledged</h2>
<p>This incident passed its acknowledgment deadline ${mins} minute(s) ago.</p>
<ul>
<li><b>Incident ID:</b> ${esc(r.incident_id)}</li>
<li><b>Category:</b> ${esc(r.category)}</li>
<li><b>Severity:</b> ${esc(r.severity)}</li>
<li><b>Location:</b> ${esc(r.location)}</li>
<li><b>Description:</b> ${esc(r.description)}</li>
<li><b>Required team:</b> ${esc(r.required_team)}</li>
<li><b>Reported at:</b> ${esc(r.created_at)}</li>
<li><b>Deadline:</b> ${esc(r.ack_deadline)}</li>
</ul></div>`;
    return {
      incident_id: r.incident_id,
      severity: r.severity,
      overdue_minutes: mins,
      telegram_text: text,
      email_subject: `[DEMO] [ESCALATION] ${r.severity} ${r.category} - ${r.location} (${r.incident_id})`,
      email_html: html,
      escalated_at: now.toISO(),
    };
  });

return [{ json: { checked_count: pending.length, overdue_count: overdue.length, overdue } }];

const info = $('Find Overdue Incidents').first().json;
return [{
  json: {
    response: {
      pending_checked: info.checked_count,
      escalated_count: info.overdue.length,
      escalated_incidents: info.overdue.map(o => ({ incident_id: o.incident_id, severity: o.severity, overdue_minutes: o.overdue_minutes })),
      message: 'Escalation check complete.',
    },
  },
}];
